INSERT INTO site_meta (id, key, value, inserted_at) VALUES ('2ce06308-561c-46e9-9a00-1c3f1de54364', 'header', '{"menu": ["O que é", "O que oferecemos", "Utilizar os equipamentos", "Requisitos", "Eventos", "Documentos", "Docentes", "Bolsistas"], "site_name": "FLUI — Fab Lab Universitário de Inovação do IFMG Ibirité", "primary_actions": ["Uso", "Empréstimo"]}', '2026-08-25T20:08:39.603719+00:00');
INSERT INTO site_meta (id, key, value, inserted_at) VALUES ('ad371a40-7064-4653-aa1b-b4ef6b933b0f', 'hero', '{"cta": ["Conhecer o FLUI", "Solicitar para eventos"], "title": "FLUI — Ambiente de Inovação", "subtitle": "Um espaço de prototipagem rápida para transformar ideias em protótipos reais e funcionais — com foco em ensino, pesquisa, extensão e eventos."}', '2026-08-25T20:08:39.603719+00:00');
INSERT INTO site_meta (id, key, value, inserted_at) VALUES ('b52a419c-d748-4ee2-80fa-72592997668c', 'about', '{"title": "O que é o FLUI?", "description": "O Fab Lab Universitário de Inovação é um laboratório de fabricação digital do IFMG Ibirité. Oferecemos um espaço de inovação onde estudantes e pesquisadores podem transformar ideias teóricas em protótipos reais e funcionais."}', '2026-08-25T20:08:39.603719+00:00');
INSERT INTO site_meta (id, key, value, inserted_at) VALUES ('9db1acc3-274c-4ef4-a89c-a0cd7336b6c6', 'access', '{"contact": "flui.ibirite@ifmg.edu.br", "events_rule": "Caso seja para eventos sem meio de comprovação pelo SUAP: o professor ou servidor responsável deve formalizar o pedido.", "who_can_use": "Estudantes que estejam desenvolvendo atividades acadêmicas formais, como projeto de extensão, pesquisa, ensino ou eventos."}', '2026-08-25T20:08:39.603719+00:00');
INSERT INTO services (id, title, description, image_path, position, inserted_at) VALUES ('ffaa7946-52c3-4ed3-a5c8-58f1abb02b00', 'Corte a laser', 'Produção e corte de peças com precisão para protótipos e componentes.', 'assets/cortealaser.jpeg', 1, '2026-08-25T20:08:39.603719+00:00');
